XposedServiceHelper.registerListener(new XposedServiceHelper.OnServiceListener() {
    @Override
    public void onServiceBind(@NonNull XposedService service) {
        Log.i("ModuleApp", "Connected to framework: " + service.getFrameworkName());
        SharedPreferences prefs = service.getRemotePreferences("config");
        prefs.edit().putBoolean("enable_feature", true).apply();
    }

    @Override
    public void onServiceDied(@NonNull XposedService service) {
        Log.w("ModuleApp", "Framework service died");
    }
});

List<HookedTarget> targets = service.getRunningTargets();
for (HookedTarget target : targets) {
    if (target.getState() == HookedTarget.State.STALE) {
        service.hotReloadModule(target, null, (t, result) -> {
            if (result.status() == HotReloadResult.Status.SUCCEEDED) {
                Log.i("ModuleApp", "Hot reload succeeded for: " + t.getProcessName());
            } else {
                Log.e("ModuleApp", "Hot reload failed: " + result.message());
            }
        });
    }
}
